CREATE TEMPORARY VIEW user_exp_mapping_${grass_region_without_quote} AS
SELECT
    user_id
    ,exp_group_id
FROM
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND is_assignment_log = 1
    AND is_search_whitelist = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW exchange_rate_${grass_region_without_quote} AS 
SELECT 
    exchange_rate
FROM 
    mp_order.dim_exchange_rate__reg_s0_live
WHERE 
    grass_date =  ${local_date}
    AND grass_region = ${grass_region};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_ads_performce_${grass_region_without_quote} AS 
SELECT
    user_id
    ,CAST(entrance AS INT) AS entrance
    ,placement
    ,pricing_type

    ,impression_cnt AS ads_impression_cnt
    ,click_cnt AS ads_click_cnt
    ,COALESCE(add_to_cart_cnt, 0) + COALESCE(add_to_cart_without_clicks_cnt,0) as ads_atc_cnt
    ,order_cnt AS ads_direct_order_cnt
    ,broad_order_cnt AS ads_broad_order_cnt
    ,ads_order_gmv_usd AS ads_direct_gmv_usd
    ,broad_gmv_amt_local/exchange_rate AS ads_broad_gmv_usd
    ,CASE 
        WHEN entrance IN (27,28) AND placement IN (3327, 3328) THEN expense_by_cpm / 100000.0 
        ELSE expenditure_amt_usd 
    END AS ads_revenue_usd
FROM 
    mp_paidads.dwd_advertise_performance_di__reg_s0_live a
    LEFT JOIN exchange_rate_${grass_region_without_quote} b
WHERE 
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
    AND user_id > 0
    AND entrance = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_ads_traffic_${grass_region_without_quote} AS 
SELECT
    user_id
    ,CAST(ads_entrance AS INT) AS entrance
    ,ads_placement AS placement
    ,pricing_type

    ,CASE WHEN display_ad_tag = 1 AND operation = 1 THEN 1 END AS ads_impression_display_cnt
    ,CASE WHEN (display_ad_tag = 0 OR display_ad_tag IS NULL) AND operation = 1 THEN 1 END AS ads_impression_not_display_cnt
    ,CASE WHEN display_ad_tag = 1 AND operation = 2 THEN 1 END AS ads_click_display_cnt
    ,CASE WHEN (display_ad_tag = 0 OR display_ad_tag IS NULL) AND operation = 2 THEN 1 END AS ads_click_not_display_cnt
FROM
    mkplpaidads_data.dwd_advertise_tracking_item_hi__reg_s0_live
WHERE
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
    AND ads_entrance = '1'
    AND COALESCE(ads_id, 0) >0
    AND user_id >0;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_performance_metrics_${grass_region_without_quote} AS 
SELECT
    exp_group_id
    ,entrance
    ,placement
    ,pricing_type

    ,SUM(ads_impression_cnt) AS ads_imp_cnt
    ,SUM(ads_click_cnt) AS ads_clk_cnt
    ,SUM(ads_atc_cnt) as ads_cart_cnt
    ,SUM(ads_direct_order_cnt) AS ads_direct_order_cnt
    ,SUM(ads_broad_order_cnt) AS ads_broad_order_cnt
    ,SUM(ads_direct_gmv_usd) AS ads_direct_gmv_usd
    ,SUM(ads_broad_gmv_usd) AS ads_broad_gmv_usd
    ,SUM(ads_revenue_usd) AS ads_revenue_usd
FROM
    dwd_ads_performce_${grass_region_without_quote} a
    INNER JOIN user_exp_mapping_${grass_region_without_quote} b
    ON a.user_id = b.user_id 
GROUP BY 1,2,3,4;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_display_metrics_${grass_region_without_quote} AS 
SELECT
    exp_group_id
    ,entrance
    ,placement
    ,pricing_type

    ,SUM(ads_impression_display_cnt) AS ads_impression_display_cnt
    ,SUM(ads_impression_not_display_cnt) AS ads_impression_not_display_cnt
    ,SUM(ads_click_display_cnt) AS ads_click_display_cnt
    ,SUM(ads_click_not_display_cnt) AS ads_click_not_display_cnt
FROM
    dwd_ads_traffic_${grass_region_without_quote} a
    INNER JOIN user_exp_mapping_${grass_region_without_quote} b
    ON a.user_id = b.user_id 
GROUP BY 1,2,3,4;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_ads_type_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    COALESCE(a.exp_group_id, b.exp_group_id) AS exp_group_id
    ,COALESCE(a.entrance, b.entrance) AS entrance
    ,COALESCE(a.placement, b.placement) AS placement
    ,COALESCE(a.pricing_type, b.pricing_type) AS pricing_type

    ,ads_imp_cnt
    ,ads_clk_cnt
    ,ads_cart_cnt
    ,ads_direct_order_cnt
    ,ads_broad_order_cnt
    ,ads_direct_gmv_usd
    ,ads_broad_gmv_usd
    ,ads_revenue_usd
    ,ads_impression_display_cnt
    ,ads_impression_not_display_cnt
    ,ads_click_display_cnt
    ,ads_click_not_display_cnt
FROM 
    dws_performance_metrics_${grass_region_without_quote} a
    FULL OUTER JOIN dws_display_metrics_${grass_region_without_quote} b 
    ON a.exp_group_id = b.exp_group_id
    AND a.entrance = b.entrance 
    AND a.placement <=> b.placement
    AND a.pricing_type <=> b.pricing_type;
